.vl_default<-function(row,design,at_default_allowed){default<-.cr_data_date(row$default_date,'default_date');start<-.cr_data_date(row$as_of,'as_of');end<-.cr_data_date(row$horizon_end,'horizon_end');if(default<start||(default==start&&!at_default_allowed)||default>end) .cr_error('VALIDATION_DEFAULT_DATE','Default outside conditioning window');reason<-.vb_observed(row,design);if(is.null(reason)&&.cr_data_date(row$outcome_known_at,'outcome_known_at')<default) .cr_error('VALIDATION_LOOKAHEAD','Outcome cannot be known before default');reason}
.vl_summary<-function(p,y,weightings,rows,draws,level){metrics<-lapply(weightings,function(w).vb_errors(p,y,w));segments<-sort(unique(vapply(rows,function(r)r$segment,character(1))));by_segment<-setNames(lapply(segments,function(segment){keep<-vapply(rows,function(r)r$segment==segment,logical(1));lapply(weightings,function(w).vb_errors(p,y,w*keep))}),segments);samples<-if(is.null(draws))NULL else lapply(draws,function(draw){out<-structure(list(),names=character());for(segment in c(list(NULL),as.list(segments))){mask<-if(is.null(segment))rep(1,length(rows))else vapply(rows,function(r)r$segment==segment,logical(1));prefix<-if(is.null(segment))''else paste0('segment/',segment,'/');for(name in names(weightings)){metrics<-.vb_errors(p,y,weightings[[name]]*draw*mask);for(metric in c('bias','mae','rmse','mean_prediction','mean_outcome'))out[paste0(prefix,name,'.',metric)]<-list(metrics[[metric]])}};out});list(metrics=list(overall=metrics,by_segment=by_segment),bands=.vb_bands(samples,level))}
lgd_backtest<-function(records,design,workout_policy,uncertainty,cluster_resamples=NULL,confidence_level=.95,context=NULL){
 d<-.vb_design(design,context);if(d$target$conditioning!='default') .cr_error('VALIDATION_TARGET','LGD is default-conditioned');rows<-.vb_records(records,d);policy<-.ex_object(workout_policy,'workout_policy');method<-policy$method;.vb_string(policy$reference,'workout reference');if(!(method%in%c('closed_only','ipcw'))) .cr_error('VALIDATION_WORKOUT','Use closed_only or explicit IPCW');draws<-.vb_draws(uncertainty,cluster_resamples,rows,confidence_level);n<-length(rows);p<-y<-w<-ead<-numeric(n);exclusions<-list();open_count<-0L
 if(method=='ipcw'){if(!identical(policy$identification,'closure_independent_of_final_lgd_given_recorded_covariates')) .cr_error('VALIDATION_SELECTION','Conditional closure identification required');.vb_string(policy$model_fingerprint,'model fingerprint');known<-.cr_data_date(policy$model_known_at,'model known_at');minimum<-.vb_number(policy$minimum_observation_probability,'minimum probability');if(minimum<=0||minimum>=1) .cr_error('VALIDATION_SELECTION','Interior positivity threshold required');if(any(vapply(rows,function(r)known>.cr_data_date(r$as_of,'as_of'),logical(1)))) .cr_error('VALIDATION_LOOKAHEAD','Closure model must precede forecasts')}
 for(i in seq_along(rows)){row<-rows[[i]];p[i]<-.vb_number(row$predicted_lgd,'predicted_lgd');reason<-.vl_default(row,d,TRUE);status<-row$workout_status;if(!(status%in%c('OPEN','CLOSED'))) .cr_error('VALIDATION_WORKOUT','Declare OPEN or CLOSED');open_count<-open_count+as.integer(status=='OPEN');prob<-1;if(method=='ipcw'){prob<-.vb_number(row$observation_probability,'observation_probability');if(prob<0||prob>1) .cr_error('VALIDATION_SELECTION','Observation probability outside [0,1]');if(prob<minimum&&is.null(reason))reason<-'INSUFFICIENT_SELECTION_SUPPORT'};if(is.null(reason)&&status=='OPEN')reason<-'OPEN_WORKOUT'
 if(is.null(reason)){closed<-.cr_data_date(row$workout_closed_at,'workout_closed_at');if(closed<.cr_data_date(row$default_date,'default_date')||closed>.cr_data_date(row$outcome_known_at,'outcome_known_at')) .cr_error('VALIDATION_WORKOUT','Closure must follow default and precede final outcome');y[i]<-.vb_number(row$realized_lgd,'realized_lgd');ead[i]<-.vb_number(row$ead_at_default,'ead_at_default',0);w[i]<-1/prob}else exclusions[[length(exclusions)+1L]]<-list(prediction_id=row$prediction_id,reason=reason)
 };summary<-.vl_summary(p,y,list(count_weighted=w,ead_weighted=w*ead),rows,draws,confidence_level);support_exclusions<-sum(vapply(exclusions,function(e)e$reason=='INSUFFICIENT_SELECTION_SUPPORT',logical(1)));diagnostics<-list(selection_support_exclusions=support_exclusions,population_estimand=if(method=='closed_only')'OBSERVED_CLOSED_WORKOUTS'else if(support_exclusions)'POSITIVE_SUPPORT_SUBPOPULATION_ONLY'else'DEFAULT_POPULATION_UNDER_DECLARED_CLOSURE_IDENTIFICATION',error_direction='PREDICTED_MINUS_OBSERVED',workout_policy=policy,open_workout_count=open_count,closed_only_selection=method=='closed_only',closed_observation_weights=as.list(w),unweighted_closed_sample_not_full_default_population=method=='closed_only',ipcw_estimator=if(method=='ipcw')'SELF_NORMALIZED_HAJEK_CONDITIONAL_ON_SUPPLIED_CLOSURE_MODEL'else NULL,raw_lgd_outside_unit_interval_allowed=TRUE);.vb_result('lgd_backtest',summary$metrics,d,rows,exclusions,summary$bands,context,diagnostics,'loss_fraction_error')
}
ead_backtest<-function(records,design,weighting_policy,uncertainty,cluster_resamples=NULL,confidence_level=.95,context=NULL){
 d<-.vb_design(design,context);if(d$target$conditioning!='default') .cr_error('VALIDATION_TARGET','EAD is default-conditioned');currency<-.vb_string(d$currency,'currency');rows<-.vb_records(records,d);policy<-.ex_object(weighting_policy,'weighting_policy');method<-policy$method;.vb_string(policy$reference,'weighting reference');if(!(method%in%c('equal','reference_limit','supplied'))) .cr_error('VALIDATION_WEIGHT','Unknown weighting method');draws<-.vb_draws(uncertainty,cluster_resamples,rows,confidence_level);n<-length(rows);p<-y<-w<-pc<-yc<-ccw<-numeric(n);exclusions<-denominators<-list()
 for(i in seq_along(rows)){row<-rows[[i]];if(!identical(row$currency,currency)) .cr_error('VALIDATION_CURRENCY','Currency differs from design');p[i]<-.vb_number(row$predicted_ead,'predicted_ead',0);drawn<-.vb_number(row$drawn_at_reference,'drawn_at_reference',0);limit<-.vb_number(row$limit_at_reference,'limit_at_reference',0);undrawn<-limit-drawn;status<-if(undrawn>0)'VALID'else if(undrawn==0)'FULLY_DRAWN'else'OVERLIMIT';reason<-.vl_default(row,d,FALSE)
 if(is.null(reason)){y[i]<-.vb_number(row$realized_ead,'realized_ead',0);if(!identical(row$realized_ead_date,row$default_date)) .cr_error('VALIDATION_EAD_DATE','Realized EAD date must match default');w[i]<-if(method=='equal')1 else if(method=='reference_limit')limit else .vb_number(row$weight,'weight',0);if(undrawn>0){pc[i]<-(p[i]-drawn)/undrawn;yc[i]<-(y[i]-drawn)/undrawn;ccw[i]<-w[i]}}else exclusions[[length(exclusions)+1L]]<-list(prediction_id=row$prediction_id,reason=reason);denominators[[length(denominators)+1L]]<-list(prediction_id=row$prediction_id,undrawn_at_reference=undrawn,status=status,predicted_ccf=if(is.null(reason)&&undrawn>0)pc[i]else NULL,observed_ccf=if(is.null(reason)&&undrawn>0)yc[i]else NULL)
 };excluded<-vapply(exclusions,function(e)e$prediction_id,character(1));included<-as.numeric(!vapply(rows,function(r)r$prediction_id%in%excluded,logical(1)));ead_metrics<-.vl_summary(p,y,list(unweighted=included,selected_weighting=w),rows,draws,confidence_level);ccf_metrics<-.vl_summary(pc,yc,list(unweighted=included*vapply(denominators,function(v)v$status=='VALID',logical(1)),selected_weighting=ccw),rows,draws,confidence_level);diagnostics<-list(currency=currency,error_direction='PREDICTED_MINUS_OBSERVED',weighting_policy=policy,denominators=denominators,ccf_undefined_count=sum(vapply(denominators,function(v)v$status!='VALID',logical(1))),ccf_formula='(EAD_at_default-drawn_at_reference)/(limit_at_reference-drawn_at_reference)',ccf_clipping=FALSE);.vb_result('ead_backtest',list(ead=ead_metrics$metrics,ccf=ccf_metrics$metrics),d,rows,exclusions,list(ead=ead_metrics$bands,ccf=ccf_metrics$bands),context,diagnostics,'exposure_and_ccf_error')
}
